CREATE TABLE IF NOT EXISTS cg_admin (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS cg_people (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, phone VARCHAR(20) DEFAULT NULL, memo TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(name));
CREATE TABLE IF NOT EXISTS cg_expenses (id INT AUTO_INCREMENT PRIMARY KEY, person_id INT NOT NULL, event_date DATE NOT NULL, event_type VARCHAR(100) NOT NULL, amount INT NOT NULL, memo TEXT NULL, original_date VARCHAR(100) NULL, import_key CHAR(64) NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(event_date), FOREIGN KEY(person_id) REFERENCES cg_people(id));
CREATE TABLE IF NOT EXISTS cg_message_logs (id INT AUTO_INCREMENT PRIMARY KEY, person_id INT NOT NULL, channel VARCHAR(20) NOT NULL, message TEXT NOT NULL, status VARCHAR(30) NOT NULL, result TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(person_id) REFERENCES cg_people(id));
